void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
   vec2 uv = fragCoord/iResolution.xy;
    uv -= 0.5f;
    uv.x *= iResolution.x / iResolution.y;
       uv *= 8.0f;

    vec2 m = iMouse.xy / iResolution.xy;

    m -= 0.5f;
        m.x *= iResolution.x / iResolution.y;

    m *= 8.0f;

    vec2 f = fract(uv);

    float x = step(0.98f, f.r);    
    float y = step(0.98f, f.g);


    vec3 col = vec3(mod(floor(uv.x), 2.0f) == mod(floor(uv.y), 2.0f));

    float a = smoothstep(2.0f, 2.0f - 1.9f, length(uv - m));

    if(a < 0.001f){
        col *= vec3(0.8f, 0.5f, 0.5f) * 0.1f;
    }else{
            col *= vec3(0.8f) * a;
    }


    fragColor = vec4(col,1.0);
}
